import pickle
from pathlib import Path

import cmocean as cm

# import matplotlib.colors as mcolors
import matplotlib.dates as mdates
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

import pinner2026_jpo_code
import pinner2026_jpo_code.plots

ONE_COLUMN_WIDTH = pinner2026_jpo_code.plots.ONE_COLUMN_WIDTH
TWO_COLUMN_WIDTH = pinner2026_jpo_code.plots.TWO_COLUMN_WIDTH

INTERIM_DATA_DIR: Path = pinner2026_jpo_code.DATA_DIR / "interim"
FIGURE_DIR: Path = pinner2026_jpo_code.FIGURE_DIR

AVERAGING_TIMELENGTH = "14D"

# both files are generated by scripts/Vertical_energy_propagation_from_ADCP_data/ADCP_analysis.ipynb
with open(INTERIM_DATA_DIR / "NIW_filtered.pickle", "rb") as NIW_file:
    NIW_dict = pickle.load(NIW_file)
with open(INTERIM_DATA_DIR / "IT_filtered.pickle", "rb") as IT_file:
    IT_dict = pickle.load(IT_file)

inertial_wind = pd.read_csv(INTERIM_DATA_DIR / "inertial_wind_2022_2023.csv")
inertial_wind = inertial_wind.set_index(pd.to_datetime(inertial_wind["Unnamed: 0"]))
inertial_wind = inertial_wind.drop("Unnamed: 0", axis="columns")
for _i, col in enumerate(inertial_wind.columns):
    inertial_wind[col] = inertial_wind[col].str.replace("i", "j").apply(lambda x: complex(x))
inertial_wind_at_C = inertial_wind["C"]

# --- Figure / axes layout ------------------------------------------------
# 2 columns: NIWs ,  NIWs+ITs
fig, ax = plt.subplots(
    ncols=2,
    nrows=2,
    sharey=True,
    figsize=(TWO_COLUMN_WIDTH, 4),
    layout="constrained",
)

ax[0, 0].set_title("NIWs")
ax[0, 1].set_title("NIWs + ITs")

im_main = None

# NIW plotting
for i, (name, data) in enumerate(NIW_dict.items()):
    if name == "raw":
        continue
    if "CCW" not in name:
        continue

    v_complex = data.apply(np.imag)  # v (east) velocity, before rolling mean

    # daily rolling mean of the v component, for the wide panel
    data_mean = v_complex.abs().rolling(AVERAGING_TIMELENGTH).mean()

    if "dn" in name:
        title_direction = "downwards"
    else:
        title_direction = "upwards"

    ax[i, 0].set_ylabel(title_direction)
    im_main = ax[i, 0].pcolormesh(
        data_mean.index,
        data_mean.columns,
        data_mean.to_numpy().T,
        cmap=cm.cm.speed,  # pyright: ignore[reportAttributeAccessIssue]
        vmax=0.08,
        vmin=0,
        rasterized=True,
    )

# IT plotting
for i, (name, data) in enumerate(IT_dict.items()):
    if name == "raw":
        continue
    if "CCW" not in name:
        continue

    v_complex = data.apply(np.imag)

    data_mean = v_complex.abs().rolling(AVERAGING_TIMELENGTH).mean()

    if "dn" in name:
        title_direction = "downwards"
    else:
        title_direction = "upwards"

    assert ax[i, 0].get_ylabel() == title_direction

    im_main = ax[i, 1].pcolormesh(
        data_mean.index,
        data_mean.columns,
        data_mean.to_numpy().T,
        cmap=cm.cm.speed,  # type: ignore
        vmax=0.08,
        vmin=0,
        rasterized=True,
    )

fig.supylabel("Meters above ground")

# wide panels: full record, date-formatted ticks
for axis in ax.flatten():
    # axis.set_xlim(mdates.datestr2num("2022-11-15"), mdates.datestr2num("2022-12-24"))
    locator = mdates.AutoDateLocator(minticks=3, maxticks=8)
    formatter = mdates.ConciseDateFormatter(locator)
    axis.xaxis.set_major_locator(locator)
    axis.xaxis.set_major_formatter(formatter)

# colorbar below
cbar_main = fig.colorbar(im_main, ax=ax, location="bottom", shrink=0.8, extend="max", aspect=50)
cbar_main.set_label("current speed / (m s$^{-1}$)")

for axis in ax.flatten():
    plotted_wind = (
        inertial_wind_at_C.loc[data_mean.index[0] : data_mean.index[-1]]
        .abs()
        .rolling(window=AVERAGING_TIMELENGTH)
        .mean()
    )
    twin_ax = axis.twinx()
    twin_ax.plot(
        plotted_wind.index,
        plotted_wind,
        lw=1.5,
        alpha=0.6,
        color="k",
    )

fig.get_layout_engine().set(rect=(0, 0, 0.95, 1))  # type: ignore

# right-side supylabel-style label for the twin axes, mirroring fig.supylabel
fig.text(
    0.98,
    0.5,
    r"inertial wind speed / (m s$^{-1}$)",
    rotation="vertical",
    ha="center",
    va="center",
    fontsize=plt.rcParams["figure.labelsize"],
    fontweight=plt.rcParams["figure.labelweight"],
)

fig.savefig(FIGURE_DIR / "f12_longtime_adcp.pdf", dpi=300)
plt.show()
